/* @catalog — generated by `npm run catalog:generate`; do not edit by hand.
 * Internal
 *   Functions: terms, trackTitle
 *   Constants: guard, noIdentifiers
 * Tests
 *   - a review binds one identity per member without upload evidence, so it is never stale, and its digest binds member IDs and media evidence
 *   - the shown primary Artist names come from the capture in stored order, a name repeated in another case once, never a featured, label or unshown Credit
 *   - member evidence keeps manifest order, exact and legacy durations, own numbers but never automatic ones, the primary names as artist tags and no identifiers
 *   - member evidence is total on malformed stored captures, drafts and origins
 *   - a review run is planned from the captured Album title and first usable primary name, or the submitted text with those names
 *   - a review's submitted Artist name is kept with the run and credits its searches in place of the primary names, never the members' artist evidence
 *   - Track titles come from the titles the review captured from the catalog, never from its draft, and never an edited or filename title
 *   - each member's Track-title search is credited to its own first shown primary Artist name, never an unshown or placeholder Credit
 *   - without a usable name of its own, a member is credited to the Album's first primary name that is no placeholder by name or MusicBrainz ID, else searched alone
 *   - a saved title equal to the submitted name, with its note or in another case, is not searched again, and the next one in rank takes its place
 *   - a review with numbered saved titles and a decorated primary name plans its Track titles without positions, credited to the first part, and never sends a filename
 *   - only a review compares in subset mode
 * @end-catalog */

/**
 * An existing-Album review's metadata lookup inputs without a database: the members a run binds, each member's ranking evidence,
 * the shown primary Artist names and the run plan, with its Track-title searches from the saved titles and each member's own
 * primary Artist name. All names and identifiers are synthetic.
 */
import assert from 'node:assert/strict';
import { after, test } from 'node:test';
// The database module loads first; importing adminImportService before it trips the index import cycle.
import '../../src/infrastructure/database';
import type { AdminImportDocument } from '../../src/administration/import/adminImportService';
import {
    catalogReviewFileEvidence, catalogReviewLookupFileSet, catalogReviewPrimaryNames, isCatalogReviewLookup, lookupComparisonFor, planCatalogReviewLookup
} from '../../src/administration/lookup/lookupReviewEvidence';
import { lookupStaleSlots } from '../../src/administration/lookup/metadataLookupRecord';
import type { PlannedLookupQuery } from '../../src/administration/lookup/lookupQueryPlanner';
import { numberedMembers, reviewLookupDocument, reviewSlot, reviewTrackId } from '../support/catalogReviewLookupFixtures';
import { installNetworkGuard } from '../support/networkGuard';

const guard = installNetworkGuard();
after(() => { guard.restore(); assert.deepEqual(guard.attempts, []); });

const noIdentifiers = { releaseId: null, barcode: null, catalogNumber: null };
/** A planned query's search terms; with `track`, only its Track-title searches. */
const terms = (queries: readonly PlannedLookupQuery[], track = false) => queries.filter(query => !track || query.basis === 'trackTitle').map(query => (query as { query: unknown }).query);
/** A Track-title search as planned. */
const trackTitle = (recording: string, artist: string | null, when: 'noPreselection' | 'noMatchOrPartial') =>
    ({ kind: 'musicBrainzRecordingSearch', query: { recording, ...(artist ? { artist } : {}) }, basis: 'trackTitle', when });

test('a review binds one identity per member without upload evidence, so it is never stale, and its digest binds member IDs and media evidence', () => {
    const doc = reviewLookupDocument({ members: numberedMembers([200_000, 210_000, null]) });
    const set = catalogReviewLookupFileSet(doc);
    assert.deepEqual(set.files, [0, 1, 2].map(index => ({ slotId: reviewSlot(index), operationId: null, sha256: null })));
    assert.equal(set.complete, true);
    assert.equal(catalogReviewLookupFileSet(reviewLookupDocument({ members: numberedMembers([200_000, 210_000, null]) })).digest, set.digest);
    // Other media evidence or another member changes the digest; durations and titles do not.
    const replaced = { ...doc, catalogEvidence: { ...doc.catalogEvidence, [reviewTrackId(1)]: 'evidence-replaced' } } as AdminImportDocument;
    assert.notEqual(catalogReviewLookupFileSet(replaced).digest, set.digest);
    assert.notEqual(catalogReviewLookupFileSet(reviewLookupDocument({ members: numberedMembers([200_000, 210_000]) })).digest, set.digest);
    assert.equal(catalogReviewLookupFileSet(reviewLookupDocument({ members: numberedMembers([1, 2, 3]) })).digest, set.digest);
    // No identity carries an upload, so no later file set makes one stale, whatever it holds.
    assert.deepEqual(lookupStaleSlots(set.files, []), []);
    assert.deepEqual(lookupStaleSlots(set.files, catalogReviewLookupFileSet(replaced).files), []);
    // An empty Album binds nothing and is still complete; malformed stored shapes are skipped.
    assert.deepEqual(catalogReviewLookupFileSet(reviewLookupDocument()).files, []);
    assert.equal(catalogReviewLookupFileSet(reviewLookupDocument()).complete, true);
    const malformed = { manifest: { rootLabel: '', files: [null, { slotId: 7 }, { slotId: reviewSlot(0) }] }, catalogSource: { tracks: [null, { id: 5 }] }, catalogEvidence: 'x' } as never;
    assert.deepEqual(catalogReviewLookupFileSet(malformed).files, [{ slotId: reviewSlot(0), operationId: null, sha256: null }]);
    assert.deepEqual(catalogReviewLookupFileSet({ manifest: null, catalogSource: null } as never).files, []);
});

test('the shown primary Artist names come from the capture in stored order, a name repeated in another case once, never a featured, label or unshown Credit', () => {
    const doc = reviewLookupDocument({ primaryNames: ['Synthetic Lead', ' Synthetic Second ', 'synthetic lead', ''] });
    assert.deepEqual(catalogReviewPrimaryNames(doc), ['Synthetic Lead', 'Synthetic Second']);
    const credits = (doc.catalogCapture!.album.credits ?? []).map(entry => ({ ...entry }));
    credits[1] = { ...credits[1], entryKey: null };
    credits[0] = { ...credits[0], subject: null };
    // An unshown Credit or one whose record is not ready names nothing, so the later spelling is the first usable one.
    assert.deepEqual(catalogReviewPrimaryNames({ catalogCapture: { ...doc.catalogCapture!, album: { ...doc.catalogCapture!.album, credits } } }), ['synthetic lead']);
    // A review not yet captured, or a capture this release cannot read, shows no name.
    for (const capture of [undefined, null, 'x', { album: null }, { album: { credits: 'x' } }, { album: { credits: [null, 3, { subjectType: 'artist', role: 'primary', entryKey: 'k', subject: { name: 4 } }] } }]) {
        assert.deepEqual(catalogReviewPrimaryNames({ catalogCapture: capture } as never), [], JSON.stringify(capture));
    }
});

test('member evidence keeps manifest order, exact and legacy durations, own numbers but never automatic ones, the primary names as artist tags and no identifiers', () => {
    const members = [{ durationMs: 200_000, discNumber: 1, trackNumber: 1 }, { durationMs: 211_000, legacy: true, discNumber: 2, trackNumber: 1 }, { trackNumber: 3 }];
    const doc = reviewLookupDocument({ primaryNames: ['Synthetic Ensemble', 'synthetic ensemble', 'Synthetic Duo'], members,
        origins: { [`tracks:${reviewSlot(1)}:discNumber`]: 'automatic', [`tracks:${reviewSlot(2)}:trackNumber`]: 'automatic', [`tracks:${reviewSlot(0)}:trackNumber`]: 'administrator' } });
    const tags = ['Synthetic Ensemble', 'Synthetic Duo'];
    assert.deepEqual(catalogReviewFileEvidence(doc), [
        { slotId: reviewSlot(0), order: 0, durationMs: 200_000, durationPrecisionMs: 0, discNumber: 1, trackNumber: 1, artistTags: tags, identifiers: noIdentifiers },
        // A number lookup wrote (automatic) never constrains pairing.
        { slotId: reviewSlot(1), order: 1, durationMs: 211_000, durationPrecisionMs: 1000, discNumber: null, trackNumber: 1, artistTags: tags, identifiers: noIdentifiers },
        // A member that captured no duration is unknown.
        { slotId: reviewSlot(2), order: 2, durationMs: null, durationPrecisionMs: 0, discNumber: null, trackNumber: null, artistTags: tags, identifiers: noIdentifiers }]);
    // A review not yet captured knows no duration or name; its own numbers still count.
    assert.deepEqual(catalogReviewFileEvidence(reviewLookupDocument({ members, capture: false })).map(file => [file.durationMs, file.discNumber, file.trackNumber, file.artistTags]),
        [[null, 1, 1, []], [null, 2, 1, []], [null, null, 3, []]]);
});

test('member evidence is total on malformed stored captures, drafts and origins', () => {
    const doc = reviewLookupDocument({ members: numberedMembers([200_000, 210_000]) });
    const capture = doc.catalogCapture as unknown as Record<string, unknown>;
    const variants: Partial<AdminImportDocument>[] = [
        { catalogCapture: { ...capture, members: [{ slotId: reviewSlot(0), duration: { durationMs: -5 } }, { slotId: reviewSlot(1), duration: { durationMs: 1.5, durationPrecisionMs: 7 } }] } as never },
        { catalogCapture: { ...capture, members: 'x' } as never },
        { draft: null as never }, { draft: { album: null, tracks: [null, 'x', { slotId: reviewSlot(0), discNumber: 'one', trackNumber: 0 }] } as never },
        { draftOrigins: 'x' as never }, { manifest: { rootLabel: '', files: 'x' } as never }
    ];
    for (const variant of variants) {
        const evidence = catalogReviewFileEvidence({ ...doc, ...variant } as AdminImportDocument);
        assert.ok(evidence.every(file => file.durationMs === null || Number.isSafeInteger(file.durationMs)), JSON.stringify(variant));
        assert.ok(evidence.every(file => file.discNumber === null || Number.isSafeInteger(file.discNumber)));
    }
    const bad = catalogReviewFileEvidence({ ...doc, ...variants[0] } as AdminImportDocument);
    assert.deepEqual(bad.map(file => [file.durationMs, file.durationPrecisionMs]), [[null, 0], [null, 0]]);
    assert.deepEqual(catalogReviewFileEvidence({ ...doc, ...variants[3] } as AdminImportDocument).map(file => [file.discNumber, file.trackNumber]), [[null, null], [null, null]]);
    assert.deepEqual(catalogReviewFileEvidence({ ...doc, ...variants[5] } as AdminImportDocument), []);
});

test('a review run is planned from the captured Album title and first usable primary name, or the submitted text with those names', () => {
    const doc = reviewLookupDocument({ title: 'Synthetic Album (2013 Remaster)', primaryNames: ['Various Artists', 'Synthetic Ensemble'], members: numberedMembers([200_000, 210_000]) });
    // The administrator's edited draft title is not the saved title.
    (doc.draft as { album: { title: string } }).album.title = 'Edited Title';
    const catalog = planCatalogReviewLookup(doc);
    assert.deepEqual(catalog.input, { trigger: 'catalog', submitted: null });
    // The four title searches, then the two saved Track titles credited to the first usable primary name.
    assert.deepEqual(catalog.plan.queries.slice(0, 4).map(query => (query as { query: unknown }).query), [
        { release: 'Synthetic Album (2013 Remaster)', artist: 'Synthetic Ensemble' }, { release: 'Synthetic Album (2013 Remaster)' },
        { release: 'Synthetic Album', artist: 'Synthetic Ensemble' }, { release: 'Synthetic Album' }]);
    assert.deepEqual(catalog.plan.queries.slice(4), [trackTitle('Synthetic Track 1', 'Synthetic Ensemble', 'noMatchOrPartial'),
        trackTitle('Synthetic Track 2', 'Synthetic Ensemble', 'noMatchOrPartial')]);
    // No original filename, edited draft value, label or featured name is ever planned, and saved titles only in Track-title searches.
    const sent = JSON.stringify(catalog.plan.queries);
    for (const text of ['synthetic-1.flac', 'Edited Title', 'Synthetic Label', 'Synthetic Guest']) assert.equal(sent.includes(text), false, text);
    assert.equal(JSON.stringify(catalog.plan.queries.filter(query => query.basis !== 'trackTitle')).includes('Synthetic Track'), false);
    const submitted = planCatalogReviewLookup(doc, { submitted: { kind: 'song', text: 'Synthetic Song' } });
    assert.deepEqual(submitted.input, { trigger: 'submitted', submitted: { kind: 'song', text: 'Synthetic Song' } });
    assert.deepEqual(terms(submitted.plan.queries), [{ recording: 'Synthetic Song', artist: 'Synthetic Ensemble' }, { recording: 'Synthetic Song' },
        { recording: 'Synthetic Track 1', artist: 'Synthetic Ensemble' }, { recording: 'Synthetic Track 2', artist: 'Synthetic Ensemble' }]);
    // A review without a readable source plans nothing; without a capture, its titles are searched bare and its Track titles alone
    // (each weighs 15, so it is distinctive enough), sent for any lack of a preselection.
    assert.deepEqual(planCatalogReviewLookup({ ...doc, catalogSource: undefined } as AdminImportDocument).plan, { queries: [], rejected: 'empty' });
    const uncaptured = planCatalogReviewLookup({ ...doc, catalogCapture: undefined } as AdminImportDocument).plan.queries;
    assert.deepEqual(terms(uncaptured), [{ release: 'Synthetic Album (2013 Remaster)' }, { release: 'Synthetic Album' }, { recording: 'Synthetic Track 1' }, { recording: 'Synthetic Track 2' }]);
    assert.deepEqual(uncaptured.slice(2), [trackTitle('Synthetic Track 1', null, 'noPreselection'), trackTitle('Synthetic Track 2', null, 'noPreselection')]);
});

test('a review\'s submitted Artist name is kept with the run and credits its searches in place of the primary names, never the members\' artist evidence', () => {
    const doc = reviewLookupDocument({ primaryNames: ['Synthetic Ensemble'], members: numberedMembers([200_000, 210_000]) });
    for (const kind of ['album', 'song'] as const) {
        const typed = planCatalogReviewLookup(doc, { submitted: { kind, text: 'Synthetic Typed Name', artist: 'Synthetic Typed' } });
        assert.deepEqual(typed.input, { trigger: 'submitted', submitted: { kind, text: 'Synthetic Typed Name', artist: 'Synthetic Typed' } });
        const field = kind === 'album' ? 'release' : 'recording';
        // The typed Artist name also credits the Track-title searches.
        assert.deepEqual(typed.plan.queries.map(query => (query as { query: unknown }).query),
            [{ [field]: 'Synthetic Typed Name', artist: 'Synthetic Typed' }, { [field]: 'Synthetic Typed Name' },
                { recording: 'Synthetic Track 1', artist: 'Synthetic Typed' }, { recording: 'Synthetic Track 2', artist: 'Synthetic Typed' }], kind);
        assert.equal(JSON.stringify(typed.plan).includes('Synthetic Ensemble'), false, kind);
    }
    // Another shape or one that cannot be sent is dropped, so the name is still searched and the primary names credit it again.
    for (const artist of [7, 'https://example.invalid/a']) {
        const malformed = planCatalogReviewLookup(doc, { submitted: { kind: 'album', text: 'Synthetic Typed Name', artist: artist as never } });
        assert.deepEqual(malformed.input, { trigger: 'submitted', submitted: { kind: 'album', text: 'Synthetic Typed Name' } }, String(artist));
        assert.deepEqual(malformed.plan.queries.map(query => (query as { query: unknown }).query),
            [{ release: 'Synthetic Typed Name', artist: 'Synthetic Ensemble' }, { release: 'Synthetic Typed Name' },
                { recording: 'Synthetic Track 1', artist: 'Synthetic Ensemble' }, { recording: 'Synthetic Track 2', artist: 'Synthetic Ensemble' }], String(artist));
    }
    // The ranking's artist evidence stays the primary names: a typed Artist name is never evidence.
    assert.deepEqual(catalogReviewFileEvidence(doc).map(file => file.artistTags), [['Synthetic Ensemble'], ['Synthetic Ensemble']]);
});

test('Track titles come from the titles the review captured from the catalog, never from its draft, and never an edited or filename title', () => {
    const doc = reviewLookupDocument({ members: [{ durationMs: 200_000, title: 'Saved First Title' }, { durationMs: 210_000, title: 'synthetic-2' },
        { durationMs: 220_000, title: 'Saved Third Title' }] });
    // An edited draft title is not a saved title; the second member's saved title equals its retained filename without the extension.
    (doc.draft as { tracks: { title: string }[] }).tracks[0].title = 'Edited Track Title';
    const planned = planCatalogReviewLookup(doc).plan.queries;
    assert.deepEqual(terms(planned, true), [{ recording: 'Saved First Title', artist: 'Synthetic Ensemble' }, { recording: 'Saved Third Title', artist: 'Synthetic Ensemble' }]);
    const sent = JSON.stringify(planned);
    for (const text of ['Edited Track Title', 'synthetic-2', '.flac']) assert.equal(sent.includes(text), false, text);
    // A malformed source track or one without a string title gives none, and the rest still plan.
    const source = doc.catalogSource as unknown as { tracks: unknown[] };
    const malformed = { ...doc, catalogSource: { ...source, tracks: [null, 7, { ...(source.tracks[0] as object), title: 4 }, source.tracks[2]] } } as unknown as AdminImportDocument;
    assert.deepEqual(terms(planCatalogReviewLookup(malformed).plan.queries, true), [{ recording: 'Saved Third Title', artist: 'Synthetic Ensemble' }]);
});

test('each member\'s Track-title search is credited to its own first shown primary Artist name, never an unshown or placeholder Credit', () => {
    const variousArtists = '89ad4ac3-39f7-470e-963a-56509c546377';
    const doc = reviewLookupDocument({ albumEntries: [{ name: 'Synthetic Ensemble' }], members: [
        { durationMs: 200_000, title: 'First Saved Song', artists: [{ name: 'Synthetic Soloist' }, { name: 'Synthetic Second Soloist' }] },
        { durationMs: 210_000, title: 'Other Saved Song', artists: [{ name: 'Various Artists' }] },
        { durationMs: 220_000, title: 'Third Saved Song', artists: [{ name: 'Synthetic Anonymous', musicBrainzId: variousArtists }, { name: 'Synthetic Guest Soloist' }] },
        { durationMs: 230_000, title: 'Final Saved Song', artists: [{ name: 'Synthetic Featured', role: 'featured' }] }] });
    // Equal weights keep Album order, and the plan keeps two: the first member's own name, then the second's, whose placeholder
    // falls back to the Album's first name.
    assert.deepEqual(terms(planCatalogReviewLookup(doc).plan.queries, true),
        [{ recording: 'First Saved Song', artist: 'Synthetic Soloist' }, { recording: 'Other Saved Song', artist: 'Synthetic Ensemble' }]);
    // Without the first two, a placeholder by MusicBrainz ID is passed for the member's next name, and a featured Credit never counts.
    const rest = { ...doc, catalogSource: { ...doc.catalogSource!, tracks: doc.catalogSource!.tracks.slice(2) } } as AdminImportDocument;
    assert.deepEqual(terms(planCatalogReviewLookup(rest).plan.queries, true),
        [{ recording: 'Third Saved Song', artist: 'Synthetic Guest Soloist' }, { recording: 'Final Saved Song', artist: 'Synthetic Ensemble' }]);
    // An unshown Credit (no draft entry) names nothing.
    const capture = doc.catalogCapture!;
    const unshown = { ...rest, catalogCapture: { ...capture, members: capture.members.map(member => ({ ...member,
        credits: member.credits?.map(entry => ({ ...entry, entryKey: null })) ?? null })) } } as AdminImportDocument;
    assert.deepEqual(terms(planCatalogReviewLookup(unshown).plan.queries, true),
        [{ recording: 'Third Saved Song', artist: 'Synthetic Ensemble' }, { recording: 'Final Saved Song', artist: 'Synthetic Ensemble' }]);
});

test('without a usable name of its own, a member is credited to the Album\'s first primary name that is no placeholder by name or MusicBrainz ID, else searched alone', () => {
    const variousArtists = '89ad4ac3-39f7-470e-963a-56509c546377';
    const members = [{ durationMs: 200_000, title: 'First Saved Song', artists: [{ name: 'Synthetic Anonymous', musicBrainzId: variousArtists }] },
        { durationMs: 210_000, title: 'Other Saved Song' }];
    // The Album's only primary Credit is Various Artists under a localized name: its title searches keep that name as before, but
    // no Track title is credited to it, so both go alone.
    const localized = reviewLookupDocument({ albumEntries: [{ name: '群星', musicBrainzId: variousArtists }], members });
    const planned = planCatalogReviewLookup(localized).plan.queries;
    assert.deepEqual(terms(planned).slice(0, 2), [{ release: 'Synthetic Album', artist: '群星' }, { release: 'Synthetic Album' }]);
    assert.deepEqual(planned.filter(query => query.basis === 'trackTitle'),
        [trackTitle('First Saved Song', null, 'noMatchOrPartial'), trackTitle('Other Saved Song', null, 'noMatchOrPartial')]);
    // A usable Album name after it credits both.
    const credited = reviewLookupDocument({ albumEntries: [{ name: '群星', musicBrainzId: variousArtists }, { name: 'Synthetic Ensemble' }], members });
    assert.deepEqual(terms(planCatalogReviewLookup(credited).plan.queries, true),
        [{ recording: 'First Saved Song', artist: 'Synthetic Ensemble' }, { recording: 'Other Saved Song', artist: 'Synthetic Ensemble' }]);
});

test('a saved title equal to the submitted name, with its note or in another case, is not searched again, and the next one in rank takes its place', () => {
    const doc = reviewLookupDocument({ members: [{ durationMs: 200_000, title: 'First Saved Song' }, { durationMs: 210_000, title: 'Second Saved Song' },
        { durationMs: 220_000, title: 'Third Saved Song' }] });
    const recordings = (text: string) => terms(planCatalogReviewLookup(doc, { submitted: { kind: 'song', text } }).plan.queries, true)
        .map(query => (query as { recording: string }).recording);
    assert.deepEqual(recordings('first saved song (Live)'), ['Second Saved Song', 'Third Saved Song']);
    assert.deepEqual(recordings('Other'), ['Second Saved Song', 'First Saved Song']);
});

test('a review with numbered saved titles and a decorated primary name plans its Track titles without positions, credited to the first part, and never sends a filename', () => {
    const decorated = '合成情緒 -Gouseijoucho-';
    const doc = reviewLookupDocument({ title: 'Synthetic Live 2', primaryNames: [decorated], members: [{ durationMs: 215_659, title: '1-01 Synthetic Night(Live)' },
        { durationMs: 382_752, title: '1-02 Synthetic Mother Goose(Live)' }] });
    // Each saved title is named like its retained file.
    for (const track of (doc.catalogSource as unknown as { tracks: { title: string; originalFileName: string }[] }).tracks) track.originalFileName = `${track.title}.wav`;
    const planned = planCatalogReviewLookup(doc).plan.queries;
    assert.deepEqual(planned, [
        { kind: 'musicBrainzReleaseSearch', query: { release: 'Synthetic Live 2', artist: '合成情緒' }, basis: 'albumText' },
        { kind: 'musicBrainzReleaseSearch', query: { release: 'Synthetic Live 2' }, basis: 'albumText' },
        { kind: 'musicBrainzReleaseSearch', query: { release: 'Synthetic Live 2', artist: decorated }, basis: 'albumText' },
        trackTitle('Synthetic Mother Goose', '合成情緒', 'noMatchOrPartial'), trackTitle('Synthetic Night', '合成情緒', 'noMatchOrPartial')
    ]);
    const sent = JSON.stringify(planned);
    for (const text of ['1-01', '1-02', '.wav', '(Live)']) assert.equal(sent.includes(text), false, text);
    // The ranking's artist evidence keeps the saved name as it is.
    assert.deepEqual(catalogReviewFileEvidence(doc).map(file => file.artistTags), [[decorated], [decorated]]);
    // A saved title ending in a slash and a part of that name is searched without the ending; a submitted name is sent as typed.
    const best = reviewLookupDocument({ title: 'Synthetic Best／合成情緒', primaryNames: [decorated] });
    assert.deepEqual(terms(planCatalogReviewLookup(best).plan.queries), [{ release: 'Synthetic Best', artist: '合成情緒' }, { release: 'Synthetic Best' },
        { release: 'Synthetic Best', artist: decorated }]);
    assert.deepEqual(terms(planCatalogReviewLookup(best, { submitted: { kind: 'album', text: 'Synthetic Best／合成情緒' } }).plan.queries), [
        { release: 'Synthetic Best／合成情緒', artist: '合成情緒' }, { release: 'Synthetic Best／合成情緒' }, { release: 'Synthetic Best／合成情緒', artist: decorated }]);
    // Positions written with dots and no space, under such a title, are removed too; titles named like their files are still searched.
    const dotted = reviewLookupDocument({ title: 'Synthetic Best／合成情緒', primaryNames: [decorated], members: [{ durationMs: 200_000, title: '1.01.Synthetic Snow' },
        { durationMs: 210_000, title: '1.02.Synthetic Will' }] });
    for (const track of (dotted.catalogSource as unknown as { tracks: { title: string; originalFileName: string }[] }).tracks) track.originalFileName = `${track.title}.flac`;
    const numbered = planCatalogReviewLookup(dotted).plan.queries;
    assert.deepEqual(terms(numbered, true), [{ recording: 'Synthetic Snow', artist: '合成情緒' }, { recording: 'Synthetic Will', artist: '合成情緒' }]);
    for (const text of ['1.0', '.flac', '／']) assert.equal(JSON.stringify(numbered).includes(text), false, text);
});

test('only a review compares in subset mode', () => {
    assert.deepEqual([isCatalogReviewLookup({ purpose: 'catalogReview' }), lookupComparisonFor({ purpose: 'catalogReview' })], [true, 'subset']);
    for (const purpose of ['import', null, undefined] as const) assert.deepEqual([isCatalogReviewLookup({ purpose }), lookupComparisonFor({ purpose })], [false, 'exact']);
});
